package com.braseiro.dnd5e;
import org.json.JSONObject;
/** Executes already-authorized deterministic supplement procedures and emits a reviewable mutation envelope. */
public final class AuthorizedMechanicalMutationEngine{
 private AuthorizedMechanicalMutationEngine(){}
 public static JSONObject execute(String ruleId,JSONObject inputs){CompiledSupplementProcedureBootstrap.install();TashaSupplementalRuntimeEngine.install();JSONObject gate=AuthorizedRuleProcedureEngine.gate(ruleId,inputs);JSONObject proc=AuthorizedRuleProcedureEngine.get(ruleId);JSONObject out=new JSONObject();try{out.put("rule_id",ruleId==null?"":ruleId).put("gate",gate);if(!gate.optBoolean("executable")||"state_rule_gate".equals(proc.optString("procedure_type"))){out.put("executed",false).put("status","blocked").put("requires_resolution",true).put("auto_mutation_allowed",false).put("authority",gate.optBoolean("registered",false)?"registered_requires_manual_resolution":"blocked_missing_compiled_rule");return out;}JSONObject result=new JSONObject();
  if("cozinheiro.snack.save_dc".equals(ruleId))result.put("save_dc",8+inputs.optInt("proficiency_bonus")+inputs.optInt("constitution_modifier"));
  else if("cozinheiro.snack.prepare".equals(ruleId)){String rest=inputs.optString("rest_type").toLowerCase();if(!("short".equals(rest)||"long".equals(rest)||"curto".equals(rest)||"longo".equals(rest))){out.put("executed",false).put("status","blocked_invalid_rest");return out;}result.put("snacks_prepared",Math.max(0,inputs.optInt("constitution_modifier"))).put("one_active_effect_per_creature",true);}
  else if("cozinheiro.snack.feed".equals(ruleId))result.put("allowed",inputs.optBoolean("within_touch")&&inputs.optBoolean("free_hand")&&inputs.optBoolean("action_available")).put("action_cost",1);
  else if("animal.training.trick".equals(ruleId)){int maxAnimals=Math.max(1,inputs.optInt("trainer_wisdom_modifier"));int maxTricks=Math.max(0,inputs.optInt("animal_intelligence")*2);result.put("eligible",inputs.optBoolean("animal_handling_proficient")&&inputs.optInt("downtime_days")>=5).put("days_required",5).put("max_simultaneous_animals",maxAnimals).put("max_memorized_tricks",maxTricks);}
  else if("animal.acclimation".equals(ruleId)){String c=inputs.optString("animal_category").toLowerCase();boolean exempt=c.contains("domestic")||c.contains("filhote")||c.contains("class")||c.contains("magic")||c.contains("magia");int required=exempt?0:(inputs.optBoolean("captive")?40:20);result.put("days_required",required).put("complete",inputs.optBoolean("animal_handling_proficient")&&inputs.optInt("downtime_days")>=required);}
  else if("animal.care.sustenance".equals(ruleId)){String s=inputs.optString("size").toLowerCase();double lb="tiny".equals(s)?0.25:("small".equals(s)||"medium".equals(s)?1:("large".equals(s)?4:("huge".equals(s)?16:("gargantuan".equals(s)?64:-1))));if(lb<0){out.put("executed",false).put("status","blocked_invalid_size");return out;}result.put("food_lb_per_day",lb).put("water_gallons_per_day",lb);}
  else if("animal.uptime".equals(ruleId))result.put("downtime_credit_days",inputs.optBoolean("long_rest")&&inputs.optBoolean("requirements_available")?0.5:0d);
  else if("cozinheiro.pouch.restock".equals(ruleId)){String m=inputs.optString("method").toLowerCase();boolean market="market".equals(m)||"mercado".equals(m);boolean forage="forage".equals(m)||"forragear".equals(m);boolean ok=(market&&inputs.optDouble("gold_available")>=10d)||(forage&&inputs.optDouble("hours_available")>=8d);result.put("eligible",ok).put("gold_cost",market?10d:0d).put("hours_cost",forage?8d:0d).put("restock_interval_days",30);}
  else if("cozinheiro.spice.retry".equals(ruleId)){String c=inputs.optString("condition").toLowerCase();int lv=inputs.optInt("cook_level");boolean condition="charmed".equals(c)||"enfeitiçado".equals(c)||"enfeiticado".equals(c)||(lv>=7&&("stunned".equals(c)||"atordoado".equals(c)))||(lv>=13&&("paralyzed".equals(c)||"paralisado".equals(c)));result.put("eligible",inputs.optBoolean("bonus_action_available")&&condition).put("retry_allowed",condition).put("bonus_action_cost",1);}
  else if("cozinheiro.accepting_orders".equals(ruleId)){int lv=inputs.optInt("cook_level");String rest=inputs.optString("rest_type").toLowerCase();boolean longRest="long".equals(rest)||"longo".equals(rest);boolean shortRest="short".equals(rest)||"curto".equals(rest);boolean eligible=(lv>=7&&longRest)||(lv>=11&&(longRest||shortRest));result.put("eligible",eligible).put("extra_snacks",eligible?Math.max(0,inputs.optInt("constitution_modifier")):0).put("extras_cannot_require_prerequisite",true);}
  else if("cozinheiro.comfort_meal".equals(ruleId)){boolean ok=inputs.optInt("cook_level")>=17&&inputs.optBoolean("shared_long_rest");result.put("eligible",ok).put("duration_multiplier",ok?2:1);}
  else if("cozinheiro.leftovers".equals(ruleId)){boolean ok=inputs.optInt("cook_level")>=20&&inputs.optBoolean("initiative_rolled")&&inputs.optInt("snacks_remaining")<=0&&inputs.optBoolean("known_snack_available");result.put("eligible",ok).put("snacks_generated",ok?1:0).put("must_be_known_preparable_snack",true);}
  else if("animal.loyalty".equals(ruleId)){int max=Math.max(0,inputs.optInt("handler_wisdom"));int cur=Math.max(0,Math.min(max,inputs.optInt("current_loyalty")));int roll=Math.max(1,Math.min(4,inputs.optInt("delta_roll")));String d=inputs.optString("direction").toLowerCase();int next=("gain".equals(d)||"ganho".equals(d))?Math.min(max,cur+roll):(("loss".equals(d)||"perda".equals(d))?Math.max(0,cur-roll):cur);result.put("loyalty_min",0).put("loyalty_max",max).put("previous_loyalty",cur).put("next_loyalty",next).put("delta_applied",next-cur);}
  else if("tasha.monster.research".equals(ruleId))result=TashaCampaignSystemsEngine.monsterResearch(inputs.optString("monster_type"),inputs.optDouble("challenge_rating",0d),inputs.optString("skill"),inputs.optInt("check_total",0));
  else if("tasha.monster.negotiate".equals(ruleId))result=TashaCampaignSystemsEngine.monsterNegotiation(inputs.optString("monster_type"),inputs.optInt("desire_roll",1),inputs.optBoolean("offer_matches_desire",false));
  else if("tasha.sidekick.create".equals(ruleId))result=TashaCampaignSystemsEngine.sidekickEligibility(inputs.optString("statblock_id"),inputs.optBoolean("friendship_established",false),inputs.optBoolean("can_speak_language",false),inputs.optString("sidekick_class"));
  else if("tasha.sidekick.level".equals(ruleId)){int current=Math.max(1,inputs.optInt("current_level",1));int gain=Math.max(1,Math.max(1,inputs.optInt("hp_die_roll",1))+inputs.optInt("constitution_modifier",0));int next=Math.min(20,current+1);result.put("next_level",next).put("hp_gain",gain).put("next_proficiency_bonus",TashaCampaignSystemsEngine.proficiencyForLevel(next));}
  else if("tasha.subclass.change".equals(ruleId))result=TashaCampaignSystemsEngine.subclassChangePlan(inputs.optInt("class_level",1),inputs.optBoolean("returning_to_previous",false),inputs.optBoolean("sudden_approved",false));
  else if(ruleId!=null&&ruleId.startsWith("xanathar.downtime."))result=XanatharDowntimeRulesEngine.execute(ruleId,inputs);
  else if(ruleId!=null&&(ruleId.startsWith("xanathar.tools.")||ruleId.startsWith("xanathar.encounter.")||ruleId.startsWith("xanathar.trap.")))result=XanatharMasterToolsRulesEngine.execute(ruleId,inputs);
  else if(ruleId!=null&&ruleId.startsWith("core2024.bastion."))result=Bastion2024RulesEngine.execute(ruleId,inputs);
  else if(ruleId!=null&&ruleId.startsWith("core2024."))result=Core2024RulesEngine.execute(ruleId,inputs);
  else if(ruleId!=null&&ruleId.startsWith("tasha.origin."))result=TashaOriginRulesEngine.execute(ruleId,inputs);
  else if(ruleId!=null&&ruleId.startsWith("tasha.feat."))result=TashaFeatRuntimeEngine.execute(ruleId,inputs);
  else if(ruleId!=null&&(ruleId.startsWith("tasha.artificer.")||ruleId.startsWith("tasha.infusion.")||ruleId.startsWith("tasha.class.")||ruleId.startsWith("tasha.invocation.")||ruleId.startsWith("tasha.maneuver.")||ruleId.startsWith("tasha.style.")||ruleId.startsWith("tasha.metamagic.")))result=TashaSupplementalRuntimeEngine.resolve(ruleId,inputs);
  else {result.put("requires_resolution",true).put("auto_mutation_allowed",false);}
  JSONObject basis=SupplementContentRegistry.mechanicalBasis(ruleId);if(basis==null||basis.length()==0){JSONObject pr=AuthorizedRuleProcedureEngine.get(ruleId);basis=new JSONObject().put("source_type","authorized_rule_procedure").put("source_book",pr.optString("source_book")).put("source_locator",pr.optString("source_locator")).put("procedure_type",pr.optString("procedure_type"));}out.put("executed",true).put("status","ok").put("result",result).put("mechanical_basis",basis).put("authority","authorized_compiled_procedure");
 }catch(Exception ignored){}return out;}
 public static JSONObject mutationEnvelope(String ruleId,JSONObject inputs,JSONObject mutation){JSONObject out=execute(ruleId,inputs);try{if(!out.optBoolean("executed"))return out;JSONObject basis=out.optJSONObject("mechanical_basis");JSONObject check=DowntimeEconomyRulesEngine.validateMutation(mutation,basis);out.put("requested_mutation",mutation==null?new JSONObject():mutation).put("mutation_authorized",check.optBoolean("authorized")).put("mutation_gate",check);}catch(Exception ignored){}return out;}
}
